"use strict";(globalThis.webpackChunkgrc||=[]).push([[97778],{92478(e){e.exports=JSON.parse('[{"citeKey":"xu2026vigil","slug":"xu-2026-trigger-render-reason-multimodal-llm-agents-c360","title":"Trigger, Render, Reason: Multimodal LLM Agents for Science-Aware Scientific Simulation Monitoring","authors":["H. Xu","J. Cernuda","A. Gainaru","S. Klasky","A. Kougkas","X.-H. Sun"],"venue":"International Conference for High Performance Computing, Networking, Storage, and Analysis (SC 2026)","type":"Conference","entryType":"inproceedings","date":"November, 2026","year":2026,"era":"iit","month":11,"abstract":"Scientific simulations on leadership-class HPC systems routinely waste millions of core-hours producing invalid results, yet no tool monitors whether a running simulation computes valid science. We call this blind spot dark waste: simulations that run to completion while computing the wrong answer. We present Vigil, which couples deterministic science-aware triggers with multimodal LLM confirmation through a trigger-render-reason pipeline. Vigil instruments simulations with lightweight checks on derived-quantity operators and regions of interest; when a check detects a potential anomaly, the flagged data is rendered and analyzed by a multimodal model to assess scientific validity. Upon confirming invalid behavior, Vigil can terminate or restart the simulation from a checkpoint, preventing further expenditure on dark waste. We evaluate Vigil across four codes spanning numerical instability, pattern dynamics, turbulence dissipation, and molecular-dynamics failures. Vigil detects every deliberately configured failure with zero false positives and supplies an actionable semantic verdict for each alert.","hasAbstract":true,"lede":"We present Vigil, which couples deterministic science-aware triggers with multimodal LLM confirmation through a trigger-render-reason pipeline.","links":{"artifact":"https://doi.org/10.5281/zenodo.21844551","program":"https://sc26.conference-program.com/presentation/?id=pap1039&sess=sess236"},"tags":["Coeus","IOWarp"],"_projectIds":["iowarp","coeus"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"xu2026triggergated","slug":"xu-2026-trigger-gated-multimodal-1a84","title":"Trigger-Gated Multimodal LLM Agents for In-situ Scientific Simulation Monitoring","authors":["H. Xu","J. Cernuda","A. Kougkas","A. Gainaru","S. Klasky","X.-H. Sun","J. Lofstead"],"venue":"11th International Parallel Data Systems Workshop (PDSW 2026), held in conjunction with SC26","type":"WIP","entryType":"inproceedings","date":"November, 2026","year":2026,"era":"iit","month":11,"hasAbstract":false,"links":{"program":"https://sc26.conference-program.com/presentation/?id=ws_pdswwip113&sess=sess129"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"xu2026derivedquantity","slug":"xu-2026-rich-io-centric-derived-quantity-8c30","title":"Rich I/O-centric Derived Quantity Operators for Advanced In Situ Processing","authors":["H. Xu","J. Cernuda","A. Kougkas","X.-H. Sun","A. Gainaru","S. Klasky","M. Taufer","N. Tan","K. Assogba","M. Rafique","B. Nicolae","J. Teves","C. Brinker","L. Pouchard","J. Lofstead"],"venue":"22nd IEEE International Conference on eScience (eScience 2026)","type":"Conference","entryType":"inproceedings","date":"September, 2026","year":2026,"era":"iit","month":9,"abstract":"Scientific simulations produce increasingly large datasets that surpass practical limits for frequent input and output operations. Although performing analysis directly as data is produced (in situ) can mitigate this problem, embedding such analysis routines into complex scientific codes is often impractical or inflexible. We address this by introducing derived quantity operators that provide a modular and pluggable framework within high-level I/O libraries, enabling sophisticated in situ analysis to be performed transparently during data output with minimal modifications to the host application. The operators bind to persistent hierarchical storage through operator-declared metadata, allowing cross-timestep and cross-run analysis to be carried out seamlessly within the I/O path. We demonstrate the capabilities of our operators by integrating correctness validation and important scientific metrics, traditionally executed after simulation runs, directly into the I/O pathway as derived quantities. Our implementation illustrates how complex, non-mathematical analyses such as runtime validation can be efficiently performed during simulation, enabling early detection of errors. Our work broadens the range of in situ analyses achievable through derived quantity operators, promoting more flexible, intelligent, and reliable scientific workflows.","hasAbstract":true,"lede":"Scientific simulations produce increasingly large datasets that surpass practical limits for frequent input and output operations.","links":{"pdf":"https://grc.iit.edu/papers/2026/xu-2026-rich-io-centric-derived-quantity-8c30.pdf"},"tags":["IOWarp","Coeus"],"_projectIds":["iowarp","coeus"],"_funding":[{"agency":"DOE","award":"DE-SC0023263","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"pawar2026acropolis","slug":"pawar-2026-acropolis-1f2a","title":"Acropolis: A Portable, AI-Driven Semantic Search System for HPC","authors":["R. Pawar","L. Logan","J. Cernuda","X.-H. Sun","A. Kougkas"],"venue":"22nd IEEE International Conference on eScience (eScience 2026)","type":"Conference","entryType":"inproceedings","date":"September, 2026","year":2026,"era":"iit","month":9,"abstract":"LLM agents are now a primary interface to data repositories, but they locate files by issuing speculative regex queries through glob, grep, and file reads, creating a guess-and-check loop that is expensive in tool calls and tokens and ignores metadata embedded in scientific file formats. We present Acropolis, a semantic search system that augments a tiered filesystem with adaptive-depth content indexing and exposes it to agents through a typed natural-language interface. Acropolis provides a transparent file-summary operator in the I/O ingest path with content-addressable idempotency, a pluggable search-backend abstraction for lexical, vector, and graph engines, and an MCP server for compatible agents. On a 70-query CMIP6 retrieval benchmark, an agent using Acropolis matches the shell-tool baseline on retrieval accuracy while substantially reducing tool and backend calls per query and LLM token consumption.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2026/pawar-2026-acropolis-1f2a.pdf"},"tags":["Semantic Search","LLM Agents","HPC","Model Context Protocol"],"_projectIds":["iowarp","labios"],"_funding":[{"agency":"NSF","award":"OAC-2411318","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true},{"agency":"NSF","award":"OAC-2320345","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"bateman2026aes","slug":"bateman-2026-agent-error-simulator-3c7d","title":"Agent Error Simulator: Fault Injection for Testing Recovery in Agentic Workflows","authors":["K. Bateman","J. Cernuda","L. Logan","B. Nicolae","F. Cappello","X.-H. Sun","A. Kougkas"],"venue":"22nd IEEE International Conference on eScience (eScience 2026)","type":"Conference","entryType":"inproceedings","date":"September, 2026","year":2026,"era":"iit","month":9,"abstract":"Multi-agent large language model (LLM) workflows are increasingly deployed for complex, multi-step computational tasks. Yet the fault tolerance of these systems (how individual agents respond to malformed inputs, tool failures, and subtle numerical errors) remains poorly characterized. We present the Agent Error Simulator (AES), a benchmark framework that evaluates LLM agent fault tolerance through controlled, declarative fault injection. AES intercepts agent-to-model HTTP traffic via a transparent proxy, injecting three categories of faults (format, logic, and tool call) at configurable points in a hierarchical planner-worker-aggregator workflow. We evaluate four models spanning 2B\u201332B parameters (Qwen2.5-Coder 32B, Gemma4 27B, Mistral 7B, and Granite4 2B) across 194 jobs organized into 10 test groups covering baseline behavior, multi-error injection, workflow scale, context pressure, compaction, and detection timing. Our results reveal a model-size-dependent logic error recovery threshold between 7B and 27B parameters; universal catastrophic failure under aggregator-level logic injection; and model-specific aggregator arithmetic deficits that interact with injected faults in non-obvious ways. We release the benchmark suite, injection tooling, and result data to support reproducible multi-agent fault tolerance research.","hasAbstract":true,"lede":"We present the Agent Error Simulator (AES), a benchmark framework that evaluates LLM agent fault tolerance through controlled, declarative fault injection.","links":{"pdf":"https://grc.iit.edu/papers/2026/bateman-2026-agent-error-simulator-3c7d.pdf"},"tags":["LLM Agents","Fault Injection","Resilience","Multi-Agent Workflows"],"_projectIds":["dtio"],"_funding":[{"agency":"NSF","award":"CNS-2346504","agencyKnown":true},{"agency":"NSF","award":"CSSI-2411386","agencyKnown":true},{"agency":"NSF","award":"OAC-2411318","agencyKnown":true},{"agency":"NSF","award":"OAC-2320345","agencyKnown":true},{"agency":"DOE","award":"DE-SC0024593","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"islam2025towardsaidriven","slug":"islam-2025-towards-ai-driven-01ae","title":"Towards an AI-driven scientific workflow","authors":["S. Islam","J. Cernuda","I. Muradli","A. Kougkas","X.-H. Sun"],"venue":"21st IEEE International Conference on eScience (eScience \'25), September 15-18, 2025","type":"Technical Report","entryType":"misc","date":"September, 2025","year":2025,"era":"iit","month":9,"doi":"10.1109/escience65000.2025.00074","hasAbstract":false,"links":{"poster":"https://grc.iit.edu/papers/2025/islam-2025-towards-ai-driven-01ae-poster.pdf"},"tags":["AI","LLM","MCP","HPC"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"bateman2025dtio","slug":"bateman-2025-dtio-e77d","title":"DTIO: Data Stack for AI-driven Workflows","authors":["K. Bateman","N. Rajesh","J. Cernuda","L. Logan","B. Nicolae","F. Cappello","X.-H. Sun","A. Kougkas"],"venue":"The 37th International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Conference","entryType":"inproceedings","date":"June, 2025","year":2025,"era":"iit","month":6,"doi":"10.1145/3733723.3733736","abstract":"HPC, Big Data Analytics, and Machine Learning have become in- creasingly intertwined as popular models such as LLMs and Diffusion Models have been driving discovery in scientific fields. However, each of these domains has its own storage infrastructure with unique I/O interfaces and storage systems, requiring feature sets that are often incompatible. Users with experience in one domain lack the expertise to change their applications to match the data stacks of the other domains, necessitating expensive conversions. There is a need for a transparent solution for the unification of disparate data stacks for the triple convergence of HPC, Big Data, and ML that can provide the required functionality while achieving higher performance. To better support converged HPC, Big Data, and ML workflows, this paper proposes DTIO, a scalable I/O runtime that unifies the disparate I/O stack for modern scientific ML workflows. DTIO utilizes a unique DataTask abstraction to express the move- ment of data, its ordering, and its dependencies on other data as a task. DTIO achieves a unification of scientific and ML workflows by utilizing intelligent mapping of interfaces, and automatically de- termines the best method to relate their unique semantics. DTIO\'s online translation with DataTask caching can improve performance by 49.6% compared to offline translation methods. DTIO also offers numerous optimizations, such as asynchronous I/O and aggregation.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2025/bateman-2025-dtio-e77d.pdf"},"tags":["Task Systems","Data Stacks","Systems for AI Workflows"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"CNS-2346504","agencyKnown":true},{"agency":"NSF","award":"CSSI-2411386","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"ye2025characterizingbehavior","slug":"ye-2025-characterizing-behavior-f631","title":"Characterizing the Behavior and Impact of KV Caching on Transformer Inferences under Concurrency","authors":["J. Ye","J. Cernuda","A. Maurya","X.-H. Sun","A. Kougkas","B. Nicolae"],"venue":"The 39th IEEE International Parallel & Distributed Processing Symposium (IPDPS 2025)","type":"Conference","entryType":"inproceedings","date":"June, 2025","year":2025,"era":"iit","month":6,"doi":"10.1109/IPDPS64566.2025.00108","abstract":"Pre-training of LLMs and transformers is known to take weeks if not months even with powerful HPC systems. However, inferences are an equally important problem: once pre-trained, the model needs to serve a large number of inferences submitted under concurrency by multiple users. Thus, speeding up each inference request is instrumental in achieving high throughput and latency at scale. To avoid redundant recomputation in each decode iteration, a Key-Value (KV) cache is used to store previously computed keys (K) and values (V), speeding up token generation. GPU memory is primarily consumed by model weights and the remainder is used by the KV cache. Thus, the free GPU space available to the KV cache is a scarce resource that needs to be managed in an efficient way in order to minimize the overhead of redundant recomputations. There are many optimizations applied in this context: batching of inference requests to enable them to run in the same forward pass (and thus increase the parallelism and inference throughput), different KV cache eviction policies (simply drop KV entries and recompute them later vs. swap to host memory), etc. Under these circumstances, the decision of what batching strategy, what KV cache eviction policy to apply and how the KV cache impacts the inference performance is non-trivial. Unlike the case of pre-training, state-of-art studies are scarce in this context. To fill this gap, in this paper we study the impact of KV caching. Specifically, we instrument vLLM to measure and analyze fine-grain metrics (token throughput, KV cache memory access patterns, load balancing of the forward passes), during different inference stages (prefill, decode) in several scenarios that involve concurrent inference requests using several benchmarks. Based on the measurements and associated observations, we identify several opportunities to improve the design of inference frameworks. Index Terms-LLM inference, KV cache profiling, access pattern characterization.","hasAbstract":true,"lede":"To fill this gap, in this paper we study the impact of KV caching.","links":{"pdf":"https://grc.iit.edu/papers/2025/ye-2025-characterizing-behavior-f631.pdf"},"tags":["LABIOS"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-2411318","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true},{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"CSSI-2411386","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"bateman2025unifiedstack","slug":"bateman-2025-unified-data-stack-8de5","title":"A Unified Data Stack for AI Workflows","authors":["K. Bateman","N. Rajesh","J. Cernuda","L. Logan","B. Nicolae","F. Cappello","X.-H. Sun","A. Kougkas"],"venue":"37th International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Poster","entryType":"misc","date":"June, 2025","year":2025,"era":"iit","month":6,"hasAbstract":false,"links":{"program":"https://ssdbm.org/2025/accepted-posters.html"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"sonar2025chronologai","slug":"sonar-2025-chronolog-ai-78fe","title":"ChronoLog & AI: A Scalable, Collaborative Solution for LLM Conversation Logging & Retrieval","authors":["S. Sonar","J. Cernuda","A. Kougkas","X.-H. Sun"],"venue":"37th International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Poster","entryType":"misc","date":"June, 2025","year":2025,"era":"iit","month":6,"hasAbstract":false,"links":{"poster":"https://ssdbm.org/2025/assets/poster/0249-Sonar.pdf"},"_projectIds":["chronolog"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"sathwara2025mcpiowarp","slug":"sathwara-2025-bridging-llms-hpc-deac","title":"Bridging LLMs and HPC: A Modular MCP-IOWarp Framework for Scalable Task Execution","authors":["A. V. Sathwara","J. Cernuda","L. Logan"],"venue":"37th International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Poster","entryType":"misc","date":"June, 2025","year":2025,"era":"iit","month":6,"hasAbstract":false,"links":{"poster":"https://ssdbm.org/2025/assets/poster/6370-Aum-Sathwara.pdf"},"_projectIds":["iowarp"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"cernuda2024jarvis","slug":"cernuda-2024-jarvis-3b52","title":"Jarvis: Towards a Shared, User-Friendly, and Reproducible, I/O Infrastructure.","authors":["J. Cernuda","L. Logan","N. Lewis","S. Byna","X.-H. Sun","A. Kougkas"],"venue":"The International Parallel Data Systems Workshop (PDSW\'24)","type":"Workshop","entryType":"inproceedings","date":"November, 2024","year":2024,"era":"iit","month":11,"abstract":"Hardware is becoming increasingly heterogeneous in modern high-performance computing clusters. However, computing environments for developing tools to harness these technologies are not easily available to researchers. This work showcases the need for a new high-pace, heterogeneous I/O research cluster and presents a novel software deployment framework named Jarvis to manage its hardware diversity. Jarvis is an extensible Python framework that allows users to create Packages that deploy, manage, and monitor software, including complex applications (e.g., scientific simulations), support tools (e.g., Darshan, GDB), and storage systems (e.g., Lustre, DAOS). These packages can be combined to form complex deployment Pipelines. To ensure pipelines are portable across hardware, Jarvis defines a novel Resource Graph schema file, which is a snapshot of a cluster\'s machine-specific information. This schema can be queried by Jarvis packages to deploy software across diverse hardware compositions with minimal user effort. Index Terms-deployment, HPC, hardware abstraction, resource management, I/O, Python","hasAbstract":true,"lede":"Hardware is becoming increasingly heterogeneous in modern high-performance computing clusters.","links":{"pdf":"https://grc.iit.edu/papers/2024/cernuda-2024-jarvis-3b52.pdf"},"tags":["Deployment","HPC","Hardware Abstraction","I/O","Python","Resource Management"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"tang2024dayu","slug":"tang-2024-dayu-f286","title":"DaYu: Optimizing Distributed Scientific Workflows by Decoding Dataflow Semantics and Dynamics","authors":["M. Tang","J. Cernuda","J. Ye","L. Guo","N. Tallent","A. Kougkas","X.-H. Sun"],"venue":"2024 IEEE International Conference on Cluster Computing (CLUSTER\'24)","type":"Conference","entryType":"inproceedings","date":"September, 2024","year":2024,"era":"iit","month":9,"doi":"10.1109/cluster59578.2024.00038","abstract":"The combination of ever-growing scientific datasets and distributed workflow complexity creates I/O performance bottlenecks due to data volume, velocity, and variety. Although the increasing use of descriptive data formats (e.g., HDF5, netCDF) helps organize these datasets, it also introduces obscure bottlenecks due to the need to translate high-level operations into file addresses and then into low-level I/O operations. To address this challenge, we introduce DaYu, a method and toolset for analyzing (a) semantic relationships between logical datasets and file addresses, (b) how dataset operations translate into I/O, and (c) the combination across entire workflows. DaYu\'s analysis and visualization enable the identification of critical bottlenecks and the reasoning about remediation. We describe our methodology and propose optimization guidelines. Evaluation on scientific workflows demonstrates up to a 3.7x performance improvement in I/O time for obscure bottlenecks. The time and storage overhead for DaYu\'s time-ordered data are typically under 0.2% of runtime and 0.25% of data volume, respectively.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2024/tang-2024-dayu-f286.pdf"},"tags":["Data Analytics","Modeling","Performance Measurement","Tools","Workflow Optimization"],"_projectIds":["portus"],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"cernuda2024hstream","slug":"cernuda-2024-hstream-3043","title":"HStream: A hierarchical data streaming engine for high-throughput scientific applications","authors":["J. Cernuda","J. Ye","A. Kougkas","X.-H. Sun"],"venue":"The 53th International Conference on Parallel Processing (ICPP\'24)","type":"Conference","entryType":"inproceedings","date":"August, 2024","year":2024,"era":"iit","month":8,"doi":"10.1145/3673038.3673150","abstract":"Data streaming is gaining traction in high-performance computing (HPC) as a mechanism for continuous data transfer, but remains underutilized as a processing paradigm due to the inadequacy of existing technologies, which are primarily designed for cloud archi- tectures and ill-equipped to tackle HPC-specific challenges. This work introduces HStream, a novel data management design for out-of-core data streaming engines. Central to the HStream design is the separation of data and computing planes at the task level. By managing them independently, issues such as memory thrashing and back-pressure, caused by the high volume, velocity, and bursti- ness of I/O in HPC environments, can be effectively addressed at runtime. Specifically, HStream utilizes adaptive parallelism and hi- erarchical memory management, enabled by this design paradigm, to alleviate memory pressure and enhance system performance. These improvements enable HStream to match the performance of state-of-the-art HPC streaming engines and achieve up to a 1.5x reduction in latency under high data loads.","hasAbstract":true,"lede":"Data streaming is gaining traction in high-performance computing (HPC) as a mechanism for continuous data transfer.","links":{"pdf":"https://grc.iit.edu/papers/2024/cernuda-2024-hstream-3043.pdf"},"tags":["Data Streaming","HPC","Hierarchical Storage","Elastic System","In-Transit Computing","LABIOS"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true},{"agency":"DOE","award":"DE-SC0023263","agencyKnown":true},{"agency":"DOE","award":"DE-SC0024593","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"ye2024viper","slug":"ye-2024-viper-0a1b","title":"Viper: A High-Performance I/O Framework for Transparently Updating, Storing, and Transferring Deep Neural Network Models","authors":["J. Ye","J. Cernuda","N. Rajesh","K. Bateman","O. Yildiz","T. Peterka","A. Nigmetov","D. Morozov","A. Kougkas","X.-H. Sun","B. Nicolae"],"venue":"The 53th International Conference on Parallel Processing (ICPP\'24)","type":"Conference","entryType":"inproceedings","date":"August, 2024","year":2024,"era":"iit","month":8,"doi":"10.1145/3673038.3673070","abstract":"Scientific workflows increasingly need to train a DNN model in real-time during an experiment (e.g. using ground truth from a sim- ulation), while using it at the same time for inferences. Instead of sharing the same model instance, the training (producer) and infer- ence server (consumer) often use different model replicas that are kept synchronized. In addition to efficient I/O techniques to keep the model replica of the producer and consumer synchronized, there is another important trade-off: frequent model updates enhance infer- ence quality but may slow down training; infrequent updates may lead to less precise inference results. To address these challenges, we introduce Viper: a new I/O framework designed to determine a near- optimal checkpoint schedule and accelerate the delivery of the latest model updates. Viper builds an inference performance predictor to identify the optimal checkpoint schedule to balance the trade-off be- tween training slowdown and inference quality improvement. It also creates a memory-first model transfer engine to accelerate model delivery through direct memory-to-memory communication. Our experiments show that Viper can reduce the model update latency by \u2248 9x using the GPU-to-GPU data transfer engine and \u2248 3x using the DRAM-to-DRAM host data transfer. The checkpoint schedule obtained from Viper\'s predictor also demonstrates improved cumu- lative inference accuracy compared to the baseline of epoch-based solutions.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2024/ye-2024-viper-0a1b.pdf","slides":"https://grc.iit.edu/papers/2024/ye-2024-viper-0a1b-slides.pptx"},"tags":["AI Workflows","Adaptive AI Model Checkpointing","Coupled Training and Inferences","Inferences During Partial Training","LABIOS"],"_projectIds":["deepio"],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"cernuda2024hades","slug":"cernuda-2024-hades-e18c","title":"Hades: A Context-Aware Active Storage Framework for Accelerating Large-Scale Data Analysis","authors":["J. Cernuda","L. Logan","A. Gainaru","J. Lofstead","A. Kougkas","X.-H. Sun"],"venue":"The 24th IEEE/ACM international Symposium on Cluster, Cloud and Internet Computing (CCGRID 2024)","type":"Conference","entryType":"inproceedings","date":"May, 2024","year":2024,"era":"iit","month":5,"doi":"10.1109/ccgrid59990.2024.00070","abstract":"Modern simulation workflows generate and analyze massive amounts of data using I/O libraries like Adios2 and NetCDF. Although extensive work has optimized the I/O processes during the simulation phase, executing analytical queries-which often require iterative traversals of large files for insights-is cumbersome and usually constrained by low I/O performance. Instead of waiting for the analysis phase to process queries, quantities can be derived asynchronously during data production and cached, speeding up future queries. In this work, we introduce a context-aware I/O layer named \'Hades.\' It is designed to efficiently derive insights from selected quantities without compromising overall workflow performance. Hades actively and asynchronously computes and stores these quantities while the data is in transit. Hades leverages a hierarchical buffering system with data access-aware prefetching to ensure quick and timely access to relevant data. It offers a flexible query interface empowering users to easily define derived quantities and provide control over data placement decisions. Hades is implemented using an Adios2 plugin engine and the Hermes buffering platform, enabling transparent use by any Adios-powered application or workflow. Experimental results demonstrate performance improvements by up to 3-4x for tested real-world scientific producer-consumer workflows. Index Terms-Active Storage, Hierarchical Storage, Context Awareness, Metadata Management, Data Operator, In-transit Computing","hasAbstract":true,"lede":"We introduce a context-aware I/O layer named \'Hades.\'","links":{"pdf":"https://grc.iit.edu/papers/2024/cernuda-2024-hades-e18c.pdf"},"tags":["Active Storage","Hierarchical Storage","Context Awareness","Metadata Management","Data Operator","In-Transit Computing","Coeus"],"_projectIds":["coeus"],"_funding":[{"agency":"DOE","award":"DE-SC0023263","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"bateman2022luxio","slug":"bateman-2022-luxio-2487","title":"LuxIO: Intelligent Resource Provisioning and Auto-Configuration for Storage Services","authors":["K. Bateman","N. Rajesh","J. Cernuda","L. Logan","J. Ye","S. Herbein","A. Kougkas","X.-H. Sun"],"venue":"The 29th edition of the IEEE International Conference on High Performance Computing, Data, and Analytics (HiPC\'22)","type":"Conference","entryType":"inproceedings","date":"December, 2022","year":2022,"era":"iit","month":12,"doi":"10.1109/hipc56025.2022.00041","abstract":"Abstract-Storage in HPC is typically a single Remote and Static Storage (RSS) resource. However, applications demonstrate diverse I/O requirements that can be better served by a multi-storage approach. Cur- rent practice employs ephemeral storage systems running on either node- local or shared storage resources. Yet, the burden of provisioning and configuring intermediate storage falls solely on the users, while global job schedulers offer little to no support for custom deployments. This lack of support often leads to over- or under-provisioning of resources and poorly configured storage systems. To mitigate this, we present LuxIO, an intelli- gent storage resource provisioning and auto-configuration service. LuxIO constructs storage deployments configured to best match I/O require- ments. LuxIO-tuned storage services show performance improvements up to 2x across common applications and benchmarks, while introducing minimal overhead of 93.40 ms on top of existing job scheduling pipelines. LuxIO improves resource utilization by up to 25% in select workflows.","hasAbstract":true,"lede":"To mitigate this, we present LuxIO, an intelli- gent storage resource provisioning and auto-configuration service.","links":{"pdf":"https://grc.iit.edu/papers/2022/bateman-2022-luxio-2487.pdf"},"tags":["Resource Provisioning","I/O Behavior","Storage Auto-Tuning","ChronoLog"],"_projectIds":["chronolog"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true},{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"logan2022labstor","slug":"logan-2022-labstor-f69d","title":"LabStor: A Modular and Extensible Platform for Developing High-Performance, Customized I/O Stacks in Userspace","authors":["L. Logan","J. Cernuda","J. Lofstead","X.-H. Sun","A. Kougkas"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'22)","type":"Conference","entryType":"inproceedings","date":"November, 2022","year":2022,"era":"iit","month":11,"doi":"10.1109/sc41404.2022.00028","abstract":"Traditionally, I/O systems have been developed within the confines of a centralized OS kernel. This led to monolithic and rigid storage systems that are limited by low development speed, expressiveness, and performance. Various assumptions are imposed including reliance on the UNIX-file abstraction, the POSIX standard, and a narrow set of I/O policies. However, this monolithic design philosophy makes it difficult to develop and deploy new I/O approaches to satisfy the rapidly-evolving I/O requirements of modern scientific applications. To this end, we propose LabStor: a modular and extensible platform for developing high-performance, customized I/O stacks. Single-purpose I/O modules (e.g, I/O schedulers) can be developed in the comfort of userspace and released as plug-ins, while end-users can compose these modules to form workload- and hardware-specific I/O stacks. Evaluations show that by switching to a fully modular design, tailored I/O stacks can yield performance improvements of up to 60% in various applications.","hasAbstract":true,"lede":"To this end, we propose LabStor: a modular and extensible platform for developing high-performance, customized I/O stacks.","links":{"pdf":"https://grc.iit.edu/papers/2022/logan-2022-labstor-f69d.pdf","slides":"https://grc.iit.edu/papers/2022/logan-2022-labstor-f69d-slides.pdf"},"tags":["Clouds and Distributed Computing","Programming Frameworks","System Software","ChronoLog"],"_projectIds":["chronolog"],"_funding":[{"agency":"NSF","award":"CSR-1814872","agencyKnown":true},{"agency":"NSF","award":"OAC-2104013","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"cernuda2021hflow","slug":"cernuda-2021-hflow-2f5b","title":"HFlow: A Dynamic and Elastic Multi-Layered Data Forwarder","authors":["J. Cernuda","H. Devarajan","L. Logan","K. Bateman","N. Rajesh","J. Ye","A. Kougkas","X.-H. Sun"],"venue":"The 2021 IEEE International Conference on Cluster Computing (CLUSTER\'21), September 7-10, 2021","type":"Conference","entryType":"inproceedings","date":"September, 2021","year":2021,"era":"iit","month":9,"doi":"10.1109/cluster48925.2021.00064","abstract":"Modern applications are highly data-intensive, leading to the well-known I/O bottleneck problem. Scientists have proposed the placement of fast intermediate storage resources which aim to mask the I/O penalties. To manage these resources, three core software abstractions are being used in leadership-class computing facilities: IO Forwarders, Burst Buffers, and Data Stagers. Yet, with the rise of multi-tenant deployment in HPC systems, these software abstractions are: managed and maintained in isolation, leading to inefficient interactions; allocated statically, leading to load imbalance; exclusively bifurcated between the intermediate storage, leading to under-utilization of resources, and, in many cases, do not support in-situ operations. To this end, we present HFlow, a new class of data forwarding system that leverages a real-time data movement paradigm. HFlow introduces a unified data movement abstraction (the ByteFlow) providing data-independent tasks that can be executed anywhere and thus, enabling dynamic resource provisioning. Moreover, the processing elements executing the ByteFlows are designed to be ephemeral and, hence, enable elastic management of intermediate storage resources. Our results show that applications running under HFlow display an increase in performance of 3x when compared with state-of-the-art software solutions. Index Terms-Data streaming, I/O forwarding, elasticity, dynamicity, multi-tenant, data-intensive, I/O,data pipeline, in-transit","hasAbstract":true,"lede":"To this end, we present HFlow, a new class of data forwarding system that leverages a real-time data movement paradigm.","links":{"pdf":"https://grc.iit.edu/papers/2021/cernuda-2021-hflow-2f5b.pdf"},"tags":["Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"rajesh2021apollo","slug":"rajesh-2021-apollo-dbd8","title":"Apollo: An ML-assisted Real-Time Storage Resource Observer","authors":["N. Rajesh","H. Devarajan","J. Cernuda","K. Bateman","L. Logan","J. Ye","A. Kougkas","X.-H. Sun"],"venue":"The 30th ACM International Symposium on High-Performance Parallel and Distributed Computing (HPDC\'21), June 21-25, 2021","type":"Conference","entryType":"inproceedings","date":"June, 2021","year":2021,"era":"iit","month":6,"doi":"10.1145/3431379.3460640","abstract":"Applications and middleware services, such as data placement en- gines, I/O scheduling, and prefetching engines, require low-latency access to telemetry data in order to make optimal decisions. However, typical monitoring services store their telemetry data in a database in order to allow applications to query them, resulting in significant latency penalties. This work presents Apollo: a low-latency mon- itoring service that aims to provide applications and middleware libraries with direct access to relational telemetry data. Monitoring the system can create interference and overhead, slowing down raw performance of the resources for the job. However, having a current view of the system can aid middleware services in making more optimal decisions which can ultimately improve the overall perfor- mance. Apollo has been designed from the ground up to provide low latency, using Publish\u2013Subscribe (Pub-Sub) semantics, and low overhead, using adaptive intervals in order to change the length of time between polling the resource for telemetry data and machine learning in order to predict changes to the telemetry data between actual resource polling. This work also provides some high level abstractions called I/O curators, which can further aid middleware libraries and applications to make optimal decisions. Evaluations showcase that Apollo can achieve sub-millisecond latency for acquir- ing complex insights with a memory overhead of 57MB and CPU overhead being only 7% more than existing state-of-the-art systems.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2021/rajesh-2021-apollo-dbd8.pdf"},"tags":["HPC","Machine Learning","Resource Monitoring","Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"kougkas2020chronolog","slug":"kougkas-2020-chronolog-c458","title":"ChronoLog: A Distributed Shared Tiered Log Store with Time-based Data Ordering","authors":["A. Kougkas","H. Devarajan","K. Bateman","J. Cernuda","N. Rajesh","X.-H. Sun"],"venue":"The 36th International Conference on Massive Storage Systems and Technology (MSST\'20), Oct. 29-30, 2020","type":"Conference","entryType":"inproceedings","date":"October, 2020","year":2020,"era":"iit","month":10,"abstract":"Modern applications produce and process massive amounts of activity (or log) data. Traditional storage systems were not designed with an append-only data model and a new storage abstraction aims to fill this gap: the distributed shared log store. However, existing solutions struggle to provide a scalable, parallel, and high-performance solution that can support a diverse set of conflicting log workload requirements. Finding the tail of a distributed log is a centralized point of contention. In this paper, we show how using physical time can help alleviate the need of centralized synchronization points. We present ChronoLog, a new, distributed, shared, and multi-tiered log store that can handle more than a million tail operations per second. Evaluation results show ChronoLog\'s potential, outperforming existing solution by an order of magnitude.","hasAbstract":true,"lede":"We show how using physical time can help alleviate the need of centralized synchronization points.","links":{"pdf":"https://grc.iit.edu/papers/2020/kougkas-2020-chronolog-c458.pdf"},"tags":["Distributed Log","Shared Log","Tiered Storage","ChronoLog"],"_projectIds":["chronolog"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"cernuda2019efficientdata","slug":"cernuda-2019-efficient-data-b08d","title":"Efficient Data Eviction across Multiple Tiers of Storage","authors":["J. Cernuda","H. Trivino","H. Devarajan","A. Kougkas","X.-H. Sun"],"venue":"The International Conference for High Performance Computing, Networking, Storage and Analysis (SC\'19)","type":"Poster","entryType":"misc","date":"November, 2019","year":2019,"era":"iit","month":11,"hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2019/cernuda-2019-efficient-data-b08d.pdf","poster":"https://grc.iit.edu/papers/2019/cernuda-2019-efficient-data-b08d-poster.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"}]')}}]);